mutation login($emailAddress: EmailAddress!, $password: String!) {
  login(emailAddress: $emailAddress, password: $password) {
    __typename
    errorMessage
    message
    accountToken
    tokenExpiry
    me {
      __typename
      emailAddress
      phoneNumber
      firstName
      lastName
      userId
      company
      position
      activeOrganization {
        __typename
        id
        name
        permissions
        featureFlagMapping {
          __typename
          id
          active
          featureFlag {
            __typename
            id
            active
            featureIdentifier
          }
        }
      }
    }
  }
}
